window.GLOSSARIO_DADOS = {"acesso-aberto": {"t": "Acesso aberto (open access)", "h": "<p>Condição em que o conteúdo publicado pode ser consultado sem assinatura ou pagamento; políticas e licenças definem os usos permitidos. No OJS, o acesso pode ser configurado para a Revista e para números.</p><p><strong>Exemplo.</strong> A equipe publica o primeiro número da Revista Crivo com acesso imediato e licença CC BY 4.0.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#licenca\">Licença</a>; <a href=\"#numero\">número</a>; <a href=\"#assinatura\">assinatura</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Distribution Settings — Access”; Matriz Crivo, “Premissas institucionais e editoriais”.</small></p>", "g": "acesso-aberto"}, "administrador-do-portal": {"t": "Administrador do Portal (site administrator)", "h": "<p>Papel de maior amplitude, responsável por configurações de toda a instalação, Revistas hospedadas, idiomas, plugins e manutenção. Seu acesso é global e não depende de designação a uma submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-administrador-do-portal\" aria-haspopup=\"dialog\">Administrador do Portal</button> habilita um idioma e cria a Revista Crivo; a equipe editorial configura a Revista depois.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#gerente-da-revista\">Gerente da Revista</a>; <a href=\"#portal\">Portal</a>; <a href=\"#revista-hospedada\">Revista hospedada</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Access the Administration Menu”, “Configure OJS Site Settings” e “Create and Manage Hosted Journals”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "administrador-do-portal"}, "ver-administrador-do-site": {"t": "Administrador do site", "h": "<p class=\"remissao\">Ver <a href=\"#administrador-do-portal\"><strong>Administrador do Portal</strong></a>. O rótulo exato em português precisa ser confirmado na instalação.</p>", "g": "ver-administrador-do-site"}, "afiliacao": {"t": "Afiliação (affiliation)", "h": "<p>Metadado que registra a instituição à qual uma pessoa autora ou colaboradora está vinculada. Pode ser multilíngue e deve ser informado sem inventar dados ausentes.</p><p><strong>Exemplo.</strong> A autora registra “Tribunal de Contas do Distrito Federal” e a equipe confere o campo antes da publicação.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#contribuinte\">Contribuinte</a>; <a href=\"#metadados\">metadados</a>; <a href=\"#orcid\">ORCID</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “ORCID e afiliação”; PKP-EW, “Publication — Contributors”.</small></p>", "g": "afiliacao"}, "anonimizacao": {"t": "Anonimização (anonymization)", "h": "<p>Remoção ou ocultação de nomes e outros elementos identificadores dos arquivos e metadados usados na avaliação. A configuração do método de avaliação não substitui a conferência dos arquivos.</p><p><strong>Exemplo.</strong> Antes de enviar o manuscrito a uma <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadora</button>, o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> remove autoria das propriedades do DOCX.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#avaliacao-duplo-anonima\">Avaliação duplo-anônima</a>; <a href=\"#arquivo-de-avaliacao\">arquivo de avaliação</a>; identidade.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Review — Remove Identifying Information”; Livro Crivo, “Avaliação e proteção da identidade”.</small></p>", "g": "anonimizacao"}, "anuncio": {"t": "Anúncio (announcement)", "h": "<p>Notícia publicada no site da Revista, opcionalmente com data de expiração. O recurso precisa estar habilitado no Portal e configurado na Revista.</p><p><strong>Exemplo.</strong> A Revista Crivo divulga uma chamada para artigos com prazo definido.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> Comunicação; <a href=\"#site-da-revista\">site da Revista</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Enable Announcements”; PKP-JM, “Communications”.</small></p>", "g": "anuncio"}, "api-rest": {"t": "API REST (REST API)", "h": "<p>Interface que permite a sistemas autorizados consultar ou manipular dados do OJS por requisições estruturadas. Endpoints, autenticação e permissões dependem da versão e da configuração.</p><p><strong>Exemplo.</strong> A equipe técnica consulta a API para integrar dados públicos da Revista a um painel institucional.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#integracao\">Integração</a>; <a href=\"#oai-pmh\">OAI-PMH</a>; <a href=\"#plugin\">plugin</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-RN, “REST API Changes”.</small></p>", "g": "api-rest"}, "arquivo-de-avaliacao": {"t": "Arquivo de avaliação (review file)", "h": "<p>Versão do arquivo disponibilizada a <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadores</button> em uma rodada. Deve conter apenas o material necessário e, quando aplicável, estar anonimizada.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> seleciona o manuscrito sem identificação e não inclui a Ficha de Autoria.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#anonimizacao\">Anonimização</a>; <a href=\"#rodada-de-avaliacao\">rodada de avaliação</a>; <a href=\"#versao\">versão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Review — Prepare Files for Review”; convenção local da Revista Crivo.</small></p>", "g": "arquivo-de-avaliacao"}, "arquivo-final-editado": {"t": "Arquivo final editado (final copyedited file)", "h": "<p>Arquivo consolidado ao término da edição de texto e encaminhado à editoração. Não é ainda, necessariamente, a composição publicada.</p><p><strong>Exemplo.</strong> Após a conferência da autoria, o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-texto\" aria-haspopup=\"dialog\">Editor de Texto</button> envia o DOCX final para Editoração.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#edicao-de-texto\">Edição de texto</a>; <a href=\"#composicao-final\">composição final</a>; <a href=\"#editoracao\">editoração</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Copyediting — Upload the Final Copyedited Files” e “Move the Copyedited File to Production”.</small></p>", "g": "arquivo-final-editado"}, "arquivo-suplementar": {"t": "Arquivo suplementar (supplementary file)", "h": "<p>Arquivo associado à submissão que complementa o texto principal, como base de dados, instrumento ou anexo. Sua finalidade, visibilidade e publicação devem ser decididas pela equipe.</p><p><strong>Exemplo.</strong> A autoria envia uma planilha de dados como componente separado do manuscrito.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#componente-do-artigo\">Componente do artigo</a>; <a href=\"#submissao\">submissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Authoring — Upload Submission Files”; Livro Crivo, “Seções, categorias e componentes”.</small></p>", "g": "arquivo-suplementar"}, "ver-artigo": {"t": "Artigo", "h": "<p class=\"remissao\">Ver <a href=\"#publicacao\"><strong>Publicação</strong></a> e <a href=\"#submissao\"><strong>Submissão</strong></a>, conforme se trate do objeto publicado ou do registro em fluxo.</p>", "g": "ver-artigo"}, "assinatura": {"t": "Assinatura (subscription)", "h": "<p>Mecanismo de controle de acesso pago ou institucional disponível no OJS. Não se aplica à Revista Crivo enquanto for mantido o modelo local de acesso aberto diamante.</p><p><strong>Exemplo.</strong> Em outra Revista do Portal, o Gestor de Assinaturas cadastra uma assinatura institucional.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#acesso-aberto\">Acesso aberto</a>; <a href=\"#gestor-de-assinaturas\">Gestor de Assinaturas</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Subscriptions”; Matriz Crivo, “Premissas institucionais e editoriais”.</small></p>", "g": "assinatura"}, "assistente-da-revista": {"t": "Assistente da Revista (journal assistant)", "h": "<p>Papel configurável de apoio editorial, com acesso definido pelo conjunto de permissões e pelos estágios designados ao papel. Na Revista Crivo, o nome e o alcance efetivos precisam ser confirmados localmente.</p><p><strong>Exemplo.</strong> Uma Assistente recebe acesso à Editoração de uma submissão para conferir arquivos, sem administrar o Portal.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#designacao\">Designação</a>; <a href=\"#papel\">papel</a>; <a href=\"#permissao\">permissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles” e “Edit or Add a Role”; Locale 3.5, <code>user.role.journalAssistant</code>; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "assistente-da-revista"}, "ver-assistente-editorial": {"t": "Assistente editorial", "h": "<p class=\"remissao\">Ver <a href=\"#assistente-da-revista\"><strong>Assistente da Revista</strong></a>. Forma local possível; confirmar nome e permissões na Revista Crivo.</p>", "g": "ver-assistente-editorial"}, "autor": {"t": "Autor (author)", "h": "<p>Papel que permite criar submissões e acompanhar aquelas vinculadas à própria conta. O acesso editorial a outras submissões não decorre desse papel.</p><p><strong>Exemplo.</strong> Ana envia um artigo, responde à solicitação de revisão e acompanha a decisão pelo painel.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#contribuinte\">Contribuinte</a>; <a href=\"#submissao\">submissão</a>; <a href=\"#usuario\">usuário</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; Livro Crivo, “Cadastro, perfil e papel de Autor”.</small></p>", "g": "autor"}, "ver-autor-a-pessoa-autora": {"t": "Autor/a; pessoa autora", "h": "<p class=\"remissao\">Ver <a href=\"#autor\"><strong>Autor</strong></a>.</p>", "g": "ver-autor-a-pessoa-autora"}, "avaliacao-duplo-anonima": {"t": "Avaliação duplo-anônima (double-anonymous review)", "h": "<p>Método em que autoria e <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadores</button> não conhecem reciprocamente suas identidades durante a avaliação. Depende da configuração da Revista e de procedimentos efetivos de anonimização.</p><p><strong>Exemplo.</strong> A Revista Crivo retira a Ficha de Autoria do conjunto enviado à <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadora</button> e verifica os metadados do arquivo.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#anonimizacao\">Anonimização</a>; <a href=\"#avaliador\">Avaliador</a>; <a href=\"#metodo-de-avaliacao\">método de avaliação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Avaliação e proteção da identidade”; Matriz Crivo, “Caso transversal”.</small></p>", "g": "avaliacao-duplo-anonima"}, "avaliacao-por-pares": {"t": "Avaliação por pares (peer review)", "h": "<p>Etapa em que especialistas analisam uma submissão segundo diretrizes e método definidos pela Revista. Pode envolver uma ou mais rodadas antes da decisão editorial.</p><p><strong>Exemplo.</strong> Duas <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadoras</button> analisam o manuscrito e o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> solicita revisões à autoria.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#decisao-editorial\">Decisão editorial</a>; <a href=\"#rodada-de-avaliacao\">rodada de avaliação</a>; <a href=\"#avaliador\">Avaliador</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “The Review Stage”; PKP-RV, “Conduct a Review”.</small></p>", "g": "avaliacao-por-pares"}, "avaliador": {"t": "Avaliador (reviewer)", "h": "<p>Papel que permite responder a convites e realizar avaliações designadas. O acesso é limitado às avaliações designadas e às informações liberadas pela configuração e pelo <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button>.</p><p><strong>Exemplo.</strong> Carla aceita o convite, consulta as diretrizes, envia seu parecer e conclui a avaliação.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#avaliacao-por-pares\">Avaliação por pares</a>; <a href=\"#convite\">convite</a>; <a href=\"#rodada-de-avaliacao\">rodada de avaliação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-RV, “Respond to a Review Request” e “Conduct a Review”; PKP-JM, “Users — Get to Know Permissions and Roles”.</small></p>", "g": "avaliador"}, "ver-avaliador-a-parecerista": {"t": "Avaliador/a; parecerista", "h": "<p class=\"remissao\">Ver <a href=\"#avaliador\"><strong>Avaliador</strong></a>.</p>", "g": "ver-avaliador-a-parecerista"}, "biblioteca-da-submissao": {"t": "Biblioteca da submissão (submission library)", "h": "<p>Área para armazenar documentos de apoio ligados à submissão, sem confundi-los com os arquivos que avançam pelo fluxo editorial. A visibilidade depende do tipo do documento e das permissões.</p><p><strong>Exemplo.</strong> A equipe guarda uma autorização administrativa na biblioteca, sem enviá-la para avaliação.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#arquivo-de-avaliacao\">Arquivo de avaliação</a>; <a href=\"#discussao\">discussão</a>; <a href=\"#submissao\">submissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Biblioteca da submissão”.</small></p>", "g": "biblioteca-da-submissao"}, "cache": {"t": "Cache", "h": "<p>Conteúdo temporário usado para acelerar o sistema; em manutenção, pode ser limpo para refletir mudanças. A limpeza é função administrativa e não deve ser tratada como correção universal.</p><p><strong>Exemplo.</strong> Após ajustar um template, o Administrador limpa o cache de templates em ambiente controlado.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#administrador-do-portal\">Administrador do Portal</a>; manutenção.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Clear Data Caches” e “Clear Template Cache”.</small></p>", "g": "cache"}, "categoria": {"t": "Categoria (category)", "h": "<p>Agrupamento temático ou editorial que pode reunir publicações independentemente da seção do número. Seu uso e exibição dependem da configuração da Revista.</p><p><strong>Exemplo.</strong> A equipe associa um artigo à categoria “Governança Pública”.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#secao\">Seção</a>; <a href=\"#publicacao\">publicação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Seções, categorias e componentes”; PKP-EW, “Publication — Schedule Articles for Publication”.</small></p>", "g": "categoria"}, "coins": {"t": "COinS", "h": "<p>Forma de incorporar metadados bibliográficos legíveis por ferramentas de referência em páginas HTML. Sua disponibilidade pode depender de plugin.</p><p><strong>Exemplo.</strong> Um leitor importa os metadados do artigo para um gerenciador bibliográfico compatível.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#indexacao\">Indexação</a>; <a href=\"#metadados\">metadados</a>; <a href=\"#plugin\">plugin</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Plugins — COinS”.</small></p>", "g": "coins"}, "componente-do-artigo": {"t": "Componente do artigo (submission component)", "h": "<p>Tipo designado a um arquivo de submissão, como texto do artigo, instrumento de pesquisa ou material suplementar. A lista é configurável pela Revista.</p><p><strong>Exemplo.</strong> A autoria classifica o DOCX como “Texto do artigo” e a planilha como “Dados de pesquisa”.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#arquivo-suplementar\">Arquivo suplementar</a>; envio de arquivos.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Workflow Settings — Components”; Livro Crivo, “Seções, categorias e componentes”.</small></p>", "g": "componente-do-artigo"}, "composicao-final": {"t": "Composição final (galley)", "h": "<p>Formato de leitura publicado, como PDF, HTML ou EPUB. Um artigo pode ter mais de uma composição, cada qual com rótulo, idioma e arquivo próprios.</p><p><strong>Exemplo.</strong> A Editoração adiciona as composições “PDF” e “HTML” e confere a pré-visualização.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#editoracao\">Editoração</a>; <a href=\"#prova\">prova</a>; <a href=\"#publicacao\">publicação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Production — What Galleys Formats Can OJS Accept?” e “Add Galley Files”.</small></p>", "g": "composicao-final"}, "conta": {"t": "Conta", "h": "<p>Cadastro individual de uma pessoa no Portal. Uma mesma conta pode ter papéis diferentes em revistas diferentes da mesma instalação.</p>", "g": "conta"}, "contribuinte": {"t": "Contribuinte (contributor)", "h": "<p>Pessoa registrada nos metadados da publicação como autora, tradutora ou colaboradora, conforme o papel selecionado. Não é sinônimo automático de conta de usuário.</p><p><strong>Exemplo.</strong> O autor correspondente inclui uma coautora nos metadados, embora ela não acesse o OJS.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#autor\">Autor</a>; <a href=\"#metadados\">metadados</a>; <a href=\"#usuario\">usuário</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Inclusão de contribuintes”; PKP-EW, “Publication — Contributors”.</small></p>", "g": "contribuinte"}, "convite": {"t": "Convite (invitation)", "h": "<p>Mecanismo do OJS 3.5 para convidar uma pessoa a criar ou ativar conta e receber papéis na Revista. Papéis concedidos e validade do convite dependem da ação configurada.</p><p><strong>Exemplo.</strong> A Gerente convida uma nova <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button> e seleciona somente o papel necessário.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#conta\">Conta</a>; <a href=\"#papel\">papel</a>; <a href=\"#usuario\">usuário</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Invite a New User”; PKP-RN, “Invitations”.</small></p>", "g": "convite"}, "counter-r5": {"t": "COUNTER R5", "h": "<p>Padrão para relatórios comparáveis de uso de recursos eletrônicos. OJS 3.5 oferece relatórios compatíveis quando a coleta e o processamento estatístico estão configurados.</p><p><strong>Exemplo.</strong> A equipe exporta um relatório COUNTER R5 para analisar downloads institucionais.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#estatisticas-de-uso\">Estatísticas de uso</a>; <a href=\"#metrica\">métrica</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-ST, “Counter R5 Reports”.</small></p>", "g": "counter-r5"}, "decisao-de-triagem": {"t": "Decisão de triagem (desk decision)", "h": "<p>Decisão tomada antes da avaliação por pares, com base no escopo, nas políticas ou em requisitos editoriais. Pode encaminhar à avaliação ou encerrar a submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> rejeita na triagem um texto fora do escopo e registra a justificativa.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#submissao\">Submissão</a>; <a href=\"#triagem-editorial\">triagem editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Submission — Send to Review or Make a Desk Decision”.</small></p>", "g": "decisao-de-triagem"}, "decisao-editorial": {"t": "Decisão editorial (editorial decision)", "h": "<p>Ação registrada pelo <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> que altera o estado da submissão, como enviar à avaliação, solicitar revisões, aceitar ou rejeitar. A decisão pode gerar comunicação à autoria e movimentação no fluxo.</p><p><strong>Exemplo.</strong> Após dois pareceres, o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> solicita revisões e define o prazo no e-mail à autoria.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#decisao-de-triagem\">Decisão de triagem</a>; <a href=\"#rodada-de-avaliacao\">rodada de avaliação</a>; <a href=\"#registro-de-atividades\">registro de atividades</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Review — Make an Editorial Decision”; Livro Crivo, “Leia o fluxo como uma mudança de estado”.</small></p>", "g": "decisao-editorial"}, "designacao": {"t": "Designação (assignment)", "h": "<p>Vínculo de uma pessoa com uma submissão ou tarefa editorial específica. Ter um papel não garante acesso a todo registro: em muitos casos, o acesso exige designação.</p><p><strong>Exemplo.</strong> Uma <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button> só passa a atuar no artigo quando é designada à submissão.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#papel\">Papel</a>; <a href=\"#participante\">participante</a>; <a href=\"#permissao\">permissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Submission — Manually Assign an Editor”; Livro Crivo, “O acesso combina papel, etapa e designação”.</small></p>", "g": "designacao"}, "discussao": {"t": "Discussão (discussion)", "h": "<p>Conversa registrada dentro de um estágio da submissão, com participantes, mensagem e arquivos. Somente participantes incluídos e usuários com acesso adequado veem a discussão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-texto\" aria-haspopup=\"dialog\">Editor de Texto</button> abre uma discussão com a autoria para esclarecer uma tabela.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#participante\">Participante</a>; <a href=\"#notificacao\">notificação</a>; <a href=\"#estagio-editorial\">estágio editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Discussões”; PKP-RV, “Use Discussions to Communicate With Editors”.</small></p>", "g": "discussao"}, "doi-identificador-de-objeto-digital": {"t": "DOI — Identificador de Objeto Digital (Digital Object Identifier)", "h": "<p>Identificador persistente designado a objetos como artigos, números ou composições, conforme a política e o plugin de DOI. Criar o identificador no OJS não prova que ele foi depositado ou registrado externamente.</p><p><strong>Exemplo.</strong> A equipe designa um DOI ao artigo e só o considera registrado após confirmação da agência.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#identificador-publico\">Identificador público</a>; <a href=\"#landing-page\">landing page</a>; <a href=\"#plugin\">plugin</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Distribution Settings — DOIs”; PKP-EW, “Publication — DOIs and Indexing of Versions”.</small></p>", "g": "doi-identificador-de-objeto-digital"}, "e-mail-em-massa": {"t": "E-mail em massa (bulk email)", "h": "<p>Comunicação enviada a grupos de usuários, sujeita a habilitação, limites e restrições por papel. Não substitui comunicações registradas na submissão quando estas precisam integrar o histórico editorial.</p><p><strong>Exemplo.</strong> A Gerente envia um aviso geral aos usuários autorizados sobre uma manutenção programada.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#notificacao\">Notificação</a>; <a href=\"#template-de-e-mail\">template de e-mail</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Enable Bulk Emails” e “Restrict Bulk Emails by Role”.</small></p>", "g": "e-mail-em-massa"}, "edicao-de-texto": {"t": "Edição de texto (copyediting)", "h": "<p>Estágio posterior à aceitação em que se revisam clareza, consistência, estilo e aspectos editoriais do texto. Termina com um arquivo consolidado para editoração.</p><p><strong>Exemplo.</strong> A equipe confere citações, tabelas e nomes institucionais antes de encaminhar o artigo.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#editor-de-texto\">Editor de Texto</a>; <a href=\"#editoracao\">Editoração</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Copyediting”; Livro Crivo, “Estágio 3 — Edição de texto”.</small></p>", "g": "edicao-de-texto"}, "ver-edicao-fasciculo": {"t": "Edição; fascículo", "h": "<p class=\"remissao\">Ver <a href=\"#numero\"><strong>Número</strong></a>.</p>", "g": "ver-edicao-fasciculo"}, "editor": {"t": "Editor (editor)", "h": "<p>Papel editorial amplo que costuma acessar submissões, designar responsáveis, tomar decisões e conduzir a publicação. O alcance exato depende das permissões do papel e, em certas telas, da designação à submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> designa uma <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button>, acompanha os pareceres e registra a decisão.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#editor-de-secao\">Editor de Seção</a>; <a href=\"#gerente-da-revista\">Gerente da Revista</a>; <a href=\"#designacao\">designação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "editor"}, "editor-de-layout": {"t": "Editor de Layout (layout editor)", "h": "<p>Papel de editoração que prepara ou incorpora formatos finais de publicação. O acesso costuma depender da designação à submissão e dos estágios permitidos ao papel.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-diagramador\" aria-haspopup=\"dialog\">Editor de Layout</button> recebe o arquivo editado e gera PDF e HTML.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#composicao-final\">Composição final</a>; <a href=\"#editoracao\">Editoração</a>; <a href=\"#prova\">prova</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Production — Assign a Layout Editor”; PKP-JM, “Users — Roles”.</small></p>", "g": "editor-de-layout"}, "editor-de-secao": {"t": "Editor de Seção (section editor)", "h": "<p>Papel editorial que gerencia submissões de seções designadas ou registros aos quais foi designado. A configuração pode permitir acesso apenas às submissões designadas ou a toda a seção.</p><p><strong>Exemplo.</strong> Uma <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button> acompanha somente os artigos de “Estudos de Controle”.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#editor\">Editor</a>; <a href=\"#secao\">seção</a>; <a href=\"#designacao\">designação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles” e “Edit or Add a Role”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "editor-de-secao"}, "ver-editor-de-secao-editor-associado": {"t": "Editor de seção; editor associado", "h": "<p class=\"remissao\">Ver <a href=\"#editor-de-secao\"><strong>Editor de Seção</strong></a>. “<button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> associado” é denominação institucional e não prova equivalência de permissões.</p>", "g": "ver-editor-de-secao-editor-associado"}, "editor-de-texto": {"t": "Editor de Texto (copyeditor)", "h": "<p>Papel responsável pela revisão editorial e linguística dos arquivos aceitos e pela consolidação do texto antes da editoração. O acesso normalmente requer designação à submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-texto\" aria-haspopup=\"dialog\">Editor de Texto</button> padroniza o manuscrito, consulta a autoria e envia o arquivo final à Editoração.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#edicao-de-texto\">Edição de texto</a>; <a href=\"#arquivo-final-editado\">arquivo final editado</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Copyediting — Assign a Copyeditor”; PKP-JM, “Users — Roles”.</small></p>", "g": "editor-de-texto"}, "editoracao": {"t": "Editoração (production)", "h": "<p>Estágio em que o arquivo editado é convertido em formatos finais, as composições são conferidas e os detalhes de publicação são concluídos. A passagem para Editoração não publica automaticamente o artigo.</p><p><strong>Exemplo.</strong> A equipe cria PDF e HTML, confere metadados e agenda o artigo em um número.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#composicao-final\">Composição final</a>; <a href=\"#prova\">prova</a>; agendamento.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Production”; Livro Crivo, “Estágio 4 — Editoração”.</small></p>", "g": "editoracao"}, "estagio-editorial": {"t": "Estágio editorial (workflow stage)", "h": "<p>Espaço de trabalho correspondente a uma fase do fluxo: Submissão, Avaliação, Edição de Texto ou Editoração. Arquivos, participantes, discussões e decisões são organizados por estágio.</p><p><strong>Exemplo.</strong> Ao aceitar o artigo, o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> o envia da Avaliação para a Edição de Texto.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#fluxo-editorial\">Fluxo editorial</a>; estado; <a href=\"#submissao\">submissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Cada estágio é um espaço de trabalho” e “O fluxo editorial como mapa do trabalho”.</small></p>", "g": "estagio-editorial"}, "estatisticas-de-uso": {"t": "Estatísticas de uso (usage statistics)", "h": "<p>Contagens processadas de visualizações e downloads de objetos publicados. Dependem de coleta, processamento, filtros e período selecionado.</p><p><strong>Exemplo.</strong> A equipe compara downloads mensais do PDF sem interpretar cada acesso como uma leitura integral.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#counter-r5\">COUNTER R5</a>; <a href=\"#metrica\">métrica</a>; relatório.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-ST, “Track article views and downloads” e “Track issue views and downloads”.</small></p>", "g": "estatisticas-de-uso"}, "fila-editorial": {"t": "Fila editorial (submission queue)", "h": "<p>Conjunto de submissões exibidas no painel conforme estado, estágio, designação e filtros. Usuários diferentes podem ver filas diferentes.</p><p><strong>Exemplo.</strong> A Editora filtra as submissões sem responsável para realizar a triagem.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#painel\">Painel</a>; <a href=\"#submissao-nao-designada\">submissão não designada</a>; <a href=\"#tarefa\">tarefa</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Dashboard”; Locale 3.5, <code>editor.submissionQueue</code>.</small></p>", "g": "fila-editorial"}, "fluxo-editorial": {"t": "Fluxo editorial (editorial workflow)", "h": "<p>Sequência de estágios e decisões que acompanha uma submissão da entrada à publicação. No OJS, o fluxo padrão reúne Submissão, Avaliação, Edição de Texto e Editoração.</p><p><strong>Exemplo.</strong> O artigo passa por triagem, duas rodadas de avaliação, edição de texto e editoração.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#estagio-editorial\">Estágio editorial</a>; <a href=\"#submissao\">submissão</a>; <a href=\"#publicacao\">publicação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, conjunto dos capítulos; Livro Crivo, “O fluxo editorial como mapa do trabalho”.</small></p>", "g": "fluxo-editorial"}, "gerente-da-revista": {"t": "Gerente da Revista (journal manager)", "h": "<p>Papel que configura a Revista, fluxo, usuários, papéis, site, distribuição e plugins autorizados. Seu acesso é amplo dentro da Revista, mas não equivale à administração de todo o Portal.</p><p><strong>Exemplo.</strong> A Gerente cria seções, ajusta diretrizes e convida integrantes da equipe.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#administrador-do-portal\">Administrador do Portal</a>; <a href=\"#editor\">Editor</a>; <a href=\"#revista\">Revista</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, conjunto do guia; PKP-SA, “Configure Journal-Specific Settings”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "gerente-da-revista"}, "ver-gerente-do-periodico-gerente-da-revista": {"t": "Gerente do Periódico; Gerente da Revista", "h": "<p class=\"remissao\">Ver <a href=\"#gerente-da-revista\"><strong>Gerente da Revista</strong></a>. O curso adota “Revista”.</p>", "g": "ver-gerente-do-periodico-gerente-da-revista"}, "gestor-de-assinaturas": {"t": "Gestor de Assinaturas (subscription manager)", "h": "<p>Papel voltado à administração de assinaturas e pagamentos, quando esses recursos são usados. Na Revista Crivo, o papel tende a não ser necessário enquanto vigorar o acesso aberto diamante.</p><p><strong>Exemplo.</strong> Em uma Revista por assinatura, o Gestor renova o acesso de uma biblioteca.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#assinatura\">Assinatura</a>; <a href=\"#acesso-aberto\">acesso aberto</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Subscriptions”; Locale 3.5, <code>user.role.subscriptionManager</code>.</small></p>", "g": "gestor-de-assinaturas"}, "identificador-publico": {"t": "Identificador público (public identifier)", "h": "<p>Valor público que identifica um objeto no sistema ou em serviço externo, como DOI ou identificador personalizado. Deve ser único no escopo aplicável.</p><p><strong>Exemplo.</strong> A equipe confere se o sufixo DOI do artigo não foi usado em outro objeto.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> DOI; URL; <a href=\"#versao\">versão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Locale 3.5, <code>editor.issues.publicId</code> e mensagens de unicidade; LOJS 3.4, “Distribution Settings — Identifiers”.</small></p>", "g": "identificador-publico"}, "idioma-da-interface": {"t": "Idioma da interface (UI locale)", "h": "<p>Idioma usado nos menus, botões e mensagens do OJS. Estar instalado no Portal não significa estar habilitado para a interface da Revista.</p><p><strong>Exemplo.</strong> O Administrador instala espanhol e a Gerente decide se ele aparecerá como opção na Revista Crivo.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#idioma-de-formulario\">Idioma de formulário</a>; <a href=\"#idioma-principal\">idioma principal</a>; <a href=\"#locale\">locale</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Manage Languages”; Livro Crivo, “Idiomas e conteúdo trilíngue”.</small></p>", "g": "idioma-da-interface"}, "idioma-de-formulario": {"t": "Idioma de formulário (form locale)", "h": "<p>Idioma em que campos multilíngues de configuração e metadados podem ser preenchidos. Deve ser habilitado separadamente conforme a política da Revista.</p><p><strong>Exemplo.</strong> A equipe preenche título e resumo em português, inglês e espanhol.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#metadados-multilingues\">Metadados multilíngues</a>; <a href=\"#idioma-da-interface\">idioma da interface</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Manage Languages”; Livro Crivo, “Idiomas e conteúdo trilíngue”.</small></p>", "g": "idioma-de-formulario"}, "idioma-principal": {"t": "Idioma principal (primary locale)", "h": "<p>Locale padrão usado pela Revista ou pelo Portal como referência de exibição e preenchimento. Alterá-lo pode afetar rótulos e dados padrão, sem traduzir conteúdos já existentes.</p><p><strong>Exemplo.</strong> A Revista Crivo mantém português do Brasil como idioma principal e oferece metadados adicionais.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#idioma-da-interface\">Idioma da interface</a>; <a href=\"#locale\">locale</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Manage Languages”; Livro Crivo, “Idiomas e conteúdo trilíngue”.</small></p>", "g": "idioma-principal"}, "importacao-e-exportacao": {"t": "Importação e exportação (import/export)", "h": "<p>Operações para transferir dados em formatos suportados por plugins e ferramentas do OJS. Compatibilidade e validação dependem da versão e do formato.</p><p><strong>Exemplo.</strong> A equipe técnica exporta usuários ou publicações para migração controlada.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#integracao\">Integração</a>; <a href=\"#plugin\">plugin</a>; <a href=\"#xml\">XML</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-RN, “Import/Export”; LOJS 3.4, “Tools — Import/Export”.</small></p>", "g": "importacao-e-exportacao"}, "indexacao": {"t": "Indexação (indexing)", "h": "<p>Processo pelo qual metadados e conteúdos são descritos, expostos e recuperados por mecanismos internos ou serviços externos. A configuração do OJS não garante inclusão em qualquer índice externo.</p><p><strong>Exemplo.</strong> A equipe expõe metadados por OAI-PMH e acompanha separadamente a aceitação por um indexador.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#metadados\">Metadados</a>; <a href=\"#oai-pmh\">OAI-PMH</a>; <a href=\"#vocabulario-controlado\">vocabulário controlado</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Distribution Settings — Search Indexing”; PKP-EW, “Publication — DOIs and Indexing of Versions”.</small></p>", "g": "indexacao"}, "instalacao": {"t": "Instalação", "h": "<p>Instância técnica do OJS, também chamada neste curso de Portal, capaz de hospedar uma ou mais Revistas. Configurações globais não devem ser confundidas com configurações de cada Revista.</p><p><strong>Exemplo.</strong> O Portal do tribunal hospeda a Revista Crivo e pode, tecnicamente, hospedar outra Revista.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#portal\">Portal</a>; <a href=\"#revista-hospedada\">Revista hospedada</a>; <a href=\"#administrador-do-portal\">Administrador do Portal</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Portal, Revista e submissão”; PKP-SA, “Create and Manage Hosted Journals”.</small></p>", "g": "instalacao"}, "integracao": {"t": "Integração", "h": "<p>Conexão do OJS com outro sistema ou serviço por protocolo, API, plugin ou troca de arquivos. Requer definição de escopo, autenticação, mapeamento de dados e monitoramento.</p><p><strong>Exemplo.</strong> A equipe integra ORCID para autenticar identificadores de pesquisadores.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#api-rest\">API REST</a>; <a href=\"#oai-pmh\">OAI-PMH</a>; <a href=\"#plugin\">plugin</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Allow Users to Connect with ORCID”; PKP-RN, “REST API Changes”.</small></p>", "g": "integracao"}, "landing-page": {"t": "Landing page", "h": "<p>Página pública do artigo ou objeto que apresenta metadados e acesso aos arquivos publicados. É o destino esperado de identificadores persistentes como DOI.</p><p><strong>Exemplo.</strong> O DOI do artigo resolve para a página pública da publicação na Revista Crivo.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> DOI; <a href=\"#publicacao\">publicação</a>; URL.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Publication”; LOJS 3.4, “Distribution Settings — DOIs”.</small></p>", "g": "landing-page"}, "leitor": {"t": "Leitor (reader)", "h": "<p>Papel de usuário voltado ao acompanhamento e acesso ao conteúdo público; não concede participação editorial. Algumas notificações podem depender de cadastro e consentimento.</p><p><strong>Exemplo.</strong> Um <button type=\"button\" class=\"papel\" data-termo=\"papel-leitor\" aria-haspopup=\"dialog\">Leitor</button> cadastrado recebe aviso de novo número, se a Revista usar esse recurso.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#usuario\">Usuário</a>; <a href=\"#notificacao\">notificação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; PKP-EW, “Publication — Notify Readers”.</small></p>", "g": "leitor"}, "licenca": {"t": "Licença (license)", "h": "<p>Instrumento que declara permissões de uso do conteúdo publicado e pode ser configurado nos metadados da Revista ou publicação. Deve corresponder à política editorial vigente.</p><p><strong>Exemplo.</strong> O artigo exibe CC BY 4.0 na landing page, conforme a política da Revista Crivo.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#acesso-aberto\">Acesso aberto</a>; direitos autorais.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Distribution Settings — Permissions”; Matriz Crivo, “Premissas institucionais e editoriais”.</small></p>", "g": "licenca"}, "locale": {"t": "Locale", "h": "<p>Código e conjunto de traduções que representam uma variante linguística e regional, como <code>pt_BR</code>. Um locale pode estar instalado no Portal e habilitado de modos diferentes na Revista.</p><p><strong>Exemplo.</strong> <code>pt_BR</code> identifica o português do Brasil usado na interface principal.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#idioma-da-interface\">Idioma da interface</a>; <a href=\"#idioma-de-formulario\">idioma de formulário</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Manage Languages”; PKP-RN, “Localization”.</small></p>", "g": "locale"}, "metadados": {"t": "Metadados (metadata)", "h": "<p>Dados estruturados que descrevem a submissão e a publicação, como título, resumo, autoria, afiliação, palavras-chave, idioma e identificadores. Podem mudar ao longo do fluxo e precisam ser conferidos antes da publicação.</p><p><strong>Exemplo.</strong> Na Editoração, a equipe corrige a afiliação e confirma o título nos três idiomas.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#contribuinte\">Contribuinte</a>; DOI; <a href=\"#metadados-multilingues\">metadados multilíngues</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Metadados e diretrizes” e “Inclusão de contribuintes”; PKP-EW, “Production — Use the Publication Menu to Finalize Details”.</small></p>", "g": "metadados"}, "metadados-multilingues": {"t": "Metadados multilíngues (multilingual metadata)", "h": "<p>Valores do mesmo campo registrados em mais de um idioma, sem substituir o conteúdo original. A disponibilidade depende dos idiomas de formulário habilitados.</p><p><strong>Exemplo.</strong> O resumo é cadastrado em português do Brasil, inglês e espanhol.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#idioma-de-formulario\">Idioma de formulário</a>; tradução.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Idiomas e conteúdo trilíngue”; Matriz Crivo, “Conteúdos transversais prioritários”.</small></p>", "g": "metadados-multilingues"}, "metodo-de-avaliacao": {"t": "Método de avaliação (review method)", "h": "<p>Regra de visibilidade de identidades na avaliação, como aberta, anônima simples ou duplo-anônima. Deve ser coerente com a política e com a preparação efetiva dos arquivos.</p><p><strong>Exemplo.</strong> A Gerente configura avaliação duplo-anônima e a equipe aplica uma lista de conferência de anonimização.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#avaliacao-duplo-anonima\">Avaliação duplo-anônima</a>; <a href=\"#anonimizacao\">anonimização</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Workflow Settings — Review”; Livro Crivo, “Avaliação e proteção da identidade”.</small></p>", "g": "metodo-de-avaliacao"}, "metrica": {"t": "Métrica", "h": "<p>Medida quantitativa produzida a partir de eventos ou registros, como downloads, visualizações ou tempo de processamento. Sua interpretação exige conhecer período, unidade, filtros e limitações.</p><p><strong>Exemplo.</strong> A equipe usa o tempo médio até a decisão como sinal de fluxo, não como medida isolada de qualidade.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#estatisticas-de-uso\">Estatísticas de uso</a>; <a href=\"#relatorio-editorial\">relatório editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-ST, “Why care about statistics?” e “Monitor your editorial activity and workflow performance”.</small></p>", "g": "metrica"}, "notificacao": {"t": "Notificação (notification)", "h": "<p>Aviso gerado pelo OJS sobre tarefa, convite, decisão ou evento; pode aparecer no painel e, conforme configuração, por e-mail. Não se confunde com a discussão completa ou o registro de atividades.</p><p><strong>Exemplo.</strong> A Editora recebe aviso de que uma avaliação foi concluída.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#e-mail-em-massa\">E-mail em massa</a>; <a href=\"#tarefa\">tarefa</a>; <a href=\"#template-de-e-mail\">template de e-mail</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Submission — Manage New Submission Notifications”; PKP-RV, “Respond to a Review Request”.</small></p>", "g": "notificacao"}, "numero": {"t": "Número (issue)", "h": "<p>Unidade editorial que reúne publicações e pode ter volume, número, ano, título, capa e composição própria. Pode existir como futuro, atual, anterior, publicado ou não publicado.</p><p><strong>Exemplo.</strong> A equipe cria “v. 1, n. 1 (2027)” e agenda artigos antes de publicar o conjunto.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> Agendamento; <a href=\"#sumario\">sumário</a>; <a href=\"#publicacao-continua\">publicação contínua</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Publication — Create and Publish Issues”; Locale 3.5, chaves <code>editor.issues.*</code>.</small></p>", "g": "numero"}, "oai-pmh": {"t": "OAI-PMH", "h": "<p>Protocolo para exposição e coleta de metadados por serviços externos. Disponibilizar um endpoint não garante que um agregador fará a coleta ou aceitará os registros.</p><p><strong>Exemplo.</strong> Um indexador coleta metadados públicos da Revista a partir do endpoint OAI-PMH.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#indexacao\">Indexação</a>; interoperabilidade; <a href=\"#metadados\">metadados</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Distribution Settings — OAI”; Livro Crivo, “Para saber mais”.</small></p>", "g": "oai-pmh"}, "orcid": {"t": "ORCID (Open Researcher and Contributor ID)", "h": "<p>Identificador gratuito, único e permanente para quem pesquisa e publica. É formado por 16 dígitos, como 0000-0002-1825-0097, e acompanha a pessoa ao longo da carreira, mesmo que ela mude de nome, de instituição ou de país. Diferencia autores com nomes parecidos e liga a pessoa aos seus trabalhos e vínculos.</p><p><strong>Na Revista.</strong> Quando a autoria conecta o ORCID ao OJS, o identificador aparece na página do artigo e segue nos metadados enviados a bases e serviços, como a Crossref. Um ORCID apenas digitado não é o mesmo que um ORCID verificado: a verificação acontece quando a própria pessoa entra na conta do ORCID e autoriza a Revista. No ambiente de treinamento, a integração com o ORCID não está ativa.</p><p><strong>Exemplo.</strong> Helena conecta o seu ORCID ao se cadastrar na Revista. O identificador verificado passa a aparecer no artigo dela e não se confunde com o de outra Helena Costa.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#afiliacao\">Afiliação</a>; <a href=\"#contribuinte\">contribuinte</a>; <a href=\"#integracao\">integração</a>.</p><p><strong>Saiba mais:</strong> <a href=\"https://orcid.org/\">https://orcid.org/</a></p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Allow Users to Connect with ORCID”; Livro Crivo, “ORCID e afiliação”; ORCID, orcid.org.</small></p>", "g": "orcid"}, "painel": {"t": "Painel (dashboard)", "h": "<p>Área de trabalho autenticada que reúne submissões, tarefas e atalhos conforme os papéis e permissões do usuário. Não é a mesma coisa que o site público da Revista.</p><p><strong>Exemplo.</strong> A Editora entra no painel para localizar submissões sem responsável.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#fila-editorial\">Fila editorial</a>; <a href=\"#site-da-revista\">site da Revista</a>; <a href=\"#tarefa\">tarefa</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Dashboard”; Livro Crivo, “Site da Revista e painel editorial”.</small></p>", "g": "painel"}, "papel": {"t": "Papel (role)", "h": "<p>Conjunto nomeado de permissões e estágios de atuação designado a uma conta em uma Revista. O nome do papel não basta para determinar todo acesso: configuração e designação também importam.</p><p><strong>Exemplo.</strong> Duas pessoas têm o papel de <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editor de Seção</button>, mas veem apenas as submissões que lhes foram designadas.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#designacao\">Designação</a>; <a href=\"#permissao\">permissão</a>; <a href=\"#usuario\">usuário</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; Livro Crivo, “Conta, papel, permissão, designação e responsabilidade”.</small></p>", "g": "papel"}, "participante": {"t": "Participante (participant)", "h": "<p>Usuário incluído em um estágio de determinada submissão para executar tarefas ou participar de discussões. A inclusão pode conceder visibilidade limitada ao estágio, conforme o papel.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> adiciona o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-texto\" aria-haspopup=\"dialog\">Editor de Texto</button> como participante na etapa de Edição de Texto.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#designacao\">Designação</a>; <a href=\"#discussao\">discussão</a>; <a href=\"#estagio-editorial\">estágio editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, capítulos “Copyediting” e “Production”; Livro Crivo, “Cada estágio é um espaço de trabalho”.</small></p>", "g": "participante"}, "permissao": {"t": "Permissão (permission)", "h": "<p>Autorização para visualizar ou executar uma ação no sistema. Resulta da combinação entre papel, estágio, configuração e, em muitos casos, designação.</p><p><strong>Exemplo.</strong> Uma Assistente consegue enviar arquivos em Editoração, mas não alterar configurações da Revista.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#papel\">Papel</a>; <a href=\"#designacao\">designação</a>; <a href=\"#responsabilidade-editorial\">responsabilidade editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; Livro Crivo, “O acesso combina papel, etapa e designação”.</small></p>", "g": "permissao"}, "plugin": {"t": "Plugin", "h": "<p>Componente que adiciona ou modifica funcionalidades do OJS, como identificadores, formatos de metadados ou temas. Estar presente no código não comprova que esteja habilitado ou configurado.</p><p><strong>Exemplo.</strong> O Administrador instala um plugin compatível e a Gerente confirma sua ativação na Revista.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#integracao\">Integração</a>; <a href=\"#tema\">tema</a>; <a href=\"#versao\">versão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Manage Plugins”; PKP-RN, “New Features/Tools”.</small></p>", "g": "plugin"}, "portal": {"t": "Portal", "h": "<p>Termo usado no curso para a instalação do OJS que hospeda uma ou mais Revistas. É administrado no nível global pelo <button type=\"button\" class=\"papel\" data-termo=\"papel-administrador-do-portal\" aria-haspopup=\"dialog\">Administrador do Portal</button>.</p><p><strong>Exemplo.</strong> Uma alteração de idioma no Portal pode disponibilizar a opção para a Revista Crivo, mas ainda requer configuração local.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#instalacao\">Instalação</a>; <a href=\"#revista-hospedada\">Revista hospedada</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Portal, Revista e submissão”; PKP-SA, “Configure OJS Site Settings”.</small></p>", "g": "portal"}, "preservacao-digital": {"t": "Preservação digital (digital preservation)", "h": "<p>Conjunto de políticas e processos para manter publicações acessíveis e íntegras ao longo do tempo. No OJS, pode envolver plugins e redes de preservação, cuja participação precisa ser configurada e verificada.</p><p><strong>Exemplo.</strong> A equipe confirma se o plugin de preservação está ativo e se os conteúdos foram efetivamente transferidos.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> PKP PN; <a href=\"#plugin\">plugin</a>; pós-publicação.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Plugins — PKP Preservation Network”; PKP-JM, “Content Access”.</small></p>", "g": "preservacao-digital"}, "prova": {"t": "Prova (proof)", "h": "<p>Versão preparada para conferência antes da publicação, usada para detectar problemas de conteúdo, metadados ou apresentação. Não é sinônimo necessário de composição já publicada.</p><p><strong>Exemplo.</strong> A Assistente confere links, autoria e paginação do PDF antes do agendamento.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#composicao-final\">Composição final</a>; <a href=\"#editoracao\">Editoração</a>; pré-visualização.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Production — Format Final Proofs for Publication” e “Preview Galleys”.</small></p>", "g": "prova"}, "ver-prova-tipografica": {"t": "Prova tipográfica", "h": "<p class=\"remissao\">Ver <a href=\"#prova\"><strong>Prova</strong></a>.</p>", "g": "ver-prova-tipografica"}, "publicacao": {"t": "Publicação (publication)", "h": "<p>Conjunto versionado de metadados e arquivos que representa o artigo publicável ou publicado dentro de uma submissão. Uma submissão pode manter mais de uma versão de publicação.</p><p><strong>Exemplo.</strong> Após uma correção substancial, o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> cria uma nova versão da publicação em vez de sobrescrever silenciosamente a anterior.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#submissao\">Submissão</a>; <a href=\"#versao\">versão</a>; pós-publicação.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Production — Publication Menu” e “Publication — Versioning”.</small></p>", "g": "publicacao"}, "publicacao-continua": {"t": "Publicação contínua (continuous publication)", "h": "<p>Modelo em que artigos são publicados progressivamente em um número ou volume, sem esperar o fechamento completo do conjunto. Requer política editorial e organização coerente de números e datas.</p><p><strong>Exemplo.</strong> A Revista publica cada artigo aprovado no número corrente assim que a Editoração termina.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> Agendamento; <a href=\"#numero\">número</a>; <a href=\"#publicacao\">publicação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Matriz Crivo, “Decisões a confirmar”; PKP-EW, “Publication — Schedule Articles for Publication”.</small></p>", "g": "publicacao-continua"}, "registro-de-atividades": {"t": "Registro de atividades (activity log)", "h": "<p>Histórico de eventos relevantes da submissão, como designações, decisões, movimentações e publicação. Serve para rastreabilidade, mas não substitui a leitura de mensagens e arquivos.</p><p><strong>Exemplo.</strong> A equipe verifica quando o artigo foi enviado à avaliação e quem registrou a decisão.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> Nota editorial; <a href=\"#discussao\">discussão</a>; <a href=\"#submissao\">submissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Registro de atividades e notas”; Locale 3.5, <code>submission.eventLog</code>.</small></p>", "g": "registro-de-atividades"}, "relatorio-editorial": {"t": "Relatório editorial (editorial report)", "h": "<p>Visão agregada de atividade e desempenho do fluxo, como volume de submissões, decisões e tempos. Os resultados dependem dos filtros, datas e registros disponíveis.</p><p><strong>Exemplo.</strong> A Gerente compara o tempo mediano de avaliação entre períodos.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#estatisticas-de-uso\">Estatísticas de uso</a>; <a href=\"#metrica\">métrica</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-ST, “Monitor your editorial activity and workflow performance”.</small></p>", "g": "relatorio-editorial"}, "responsabilidade-editorial": {"t": "Responsabilidade editorial", "h": "<p>Dever institucional de decidir, conferir e responder por uma ação, que não se reduz à capacidade técnica de clicar em um comando. Pode permanecer com o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> mesmo quando uma Assistente executa tarefas operacionais.</p><p><strong>Exemplo.</strong> A Assistente prepara o agendamento, mas o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> confirma a publicação do número.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#papel\">Papel</a>; <a href=\"#permissao\">permissão</a>; <a href=\"#designacao\">designação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Conta, papel, permissão, designação e responsabilidade”.</small></p>", "g": "responsabilidade-editorial"}, "revista": {"t": "Revista (journal)", "h": "<p>Publicação configurada dentro do Portal, com identidade, site, usuários, fluxo, políticas e conteúdo próprios. Uma instalação pode hospedar várias Revistas.</p><p><strong>Exemplo.</strong> A Revista Crivo possui configurações próprias sem receber automaticamente todas as opções do Portal.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#portal\">Portal</a>; <a href=\"#revista-hospedada\">Revista hospedada</a>; <a href=\"#gerente-da-revista\">Gerente da Revista</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Create and Manage Hosted Journals”; Livro Crivo, “Portal, Revista e submissão”.</small></p>", "g": "revista"}, "revista-hospedada": {"t": "Revista hospedada (hosted journal)", "h": "<p>Revista criada e mantida em uma instalação OJS. O Administrador controla sua existência e opções globais; a Gerente controla grande parte das configurações internas.</p><p><strong>Exemplo.</strong> O Administrador adiciona a Revista Crivo ao Portal e designa uma Gerente.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#portal\">Portal</a>; <a href=\"#revista\">Revista</a>; <a href=\"#administrador-do-portal\">Administrador do Portal</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Create and Manage Hosted Journals”.</small></p>", "g": "revista-hospedada"}, "rodada-de-avaliacao": {"t": "Rodada de avaliação (review round)", "h": "<p>Ciclo específico de avaliação com arquivos, <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadores</button>, pareceres e decisão próprios. Uma nova rodada preserva a distinção entre avaliações anteriores e uma versão revisada.</p><p><strong>Exemplo.</strong> Após alterações substanciais, o <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> abre a segunda rodada com o novo manuscrito.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#avaliacao-por-pares\">Avaliação por pares</a>; revisão da autoria; <a href=\"#decisao-editorial\">decisão editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Review — Open a New Round of Review”.</small></p>", "g": "rodada-de-avaliacao"}, "secao": {"t": "Seção (section)", "h": "<p>Divisão editorial usada para classificar submissões e organizar o sumário, podendo ter políticas, formulários e <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editores</button> próprios. Não é sinônimo de categoria temática.</p><p><strong>Exemplo.</strong> O artigo é submetido à seção “Artigos”, enquanto “Governança” é usada como categoria.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#categoria\">Categoria</a>; <a href=\"#editor-de-secao\">Editor de Seção</a>; <a href=\"#numero\">número</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Journal Setup — Sections”; Livro Crivo, “Seções, categorias e componentes”.</small></p>", "g": "secao"}, "site-da-revista": {"t": "Site da Revista (journal website)", "h": "<p>Interface pública com identidade, navegação, páginas, números e publicações da Revista. Distingue-se do painel autenticado de trabalho editorial.</p><p><strong>Exemplo.</strong> Um leitor acessa o número publicado pelo site, enquanto a equipe usa o painel para preparar o próximo.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#painel\">Painel</a>; <a href=\"#tema\">tema</a>; <a href=\"#portal\">Portal</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Appearance”; Livro Crivo, “Site da Revista e painel editorial”.</small></p>", "g": "site-da-revista"}, "ver-site-instalacao": {"t": "Site; instalação", "h": "<p class=\"remissao\">Ver <a href=\"#portal\"><strong>Portal</strong></a> quando a referência for à instância global; ver <a href=\"#site-da-revista\"><strong>Site da Revista</strong></a> quando for à interface pública da publicação.</p>", "g": "ver-site-instalacao"}, "submissao": {"t": "Submissão (submission)", "h": "<p>Registro editorial criado para reunir proposta, arquivos, metadados, participantes, comunicações e decisões ao longo do fluxo. Não é apenas o arquivo do manuscrito.</p><p><strong>Exemplo.</strong> A submissão inclui o DOCX, os dados de autoria, as discussões e o histórico de decisões.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#publicacao\">Publicação</a>; <a href=\"#fluxo-editorial\">fluxo editorial</a>; <a href=\"#estagio-editorial\">estágio editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Portal, Revista e submissão” e “Recursos que acompanham a submissão”; PKP-EW, “Submission”.</small></p>", "g": "submissao"}, "submissao-incompleta": {"t": "Submissão incompleta (incomplete submission)", "h": "<p>Rascunho iniciado pela autoria que ainda não concluiu todas as etapas nem confirmou o envio. Não deve ser tratado como submissão editorial plenamente recebida.</p><p><strong>Exemplo.</strong> O autor enviou o arquivo, mas saiu antes da revisão e confirmação final.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> Nova submissão; confirmação.</p><p class=\"fonte\"><small><strong>Fonte:</strong> Livro Crivo, “Como diagnosticar uma submissão incompleta”.</small></p>", "g": "submissao-incompleta"}, "submissao-nao-designada": {"t": "Submissão não designada (unassigned submission)", "h": "<p>Submissão recebida que ainda não tem <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> responsável. A visibilidade depende de papéis com permissão para acompanhar a fila de não designadas.</p><p><strong>Exemplo.</strong> A Gerente localiza o novo artigo e designa uma <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button>.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#designacao\">Designação</a>; <a href=\"#fila-editorial\">fila editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Submission — Manage New Submission Notifications and Automatic Assignments”; Livro Crivo, “O acesso combina papel, etapa e designação”.</small></p>", "g": "submissao-nao-designada"}, "sumario": {"t": "Sumário (table of contents)", "h": "<p>Lista ordenada das publicações e seções de um número. Pode ser reorganizada antes da publicação do número.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> posiciona o editorial antes dos artigos no sumário.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#numero\">Número</a>; <a href=\"#secao\">seção</a>; <a href=\"#publicacao\">publicação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Publication — Edit an Issue: Order Table of Contents”.</small></p>", "g": "sumario"}, "tarefa": {"t": "Tarefa (task)", "h": "<p>Item de atenção exibido no painel a partir de eventos do fluxo, como convite, prazo ou mensagem. A lista varia conforme usuário, papéis e designações.</p><p><strong>Exemplo.</strong> A <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadora</button> vê uma tarefa para responder ao convite pendente.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#notificacao\">Notificação</a>; <a href=\"#painel\">painel</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Dashboard”; PKP-RV, “Respond to a Review Request”.</small></p>", "g": "tarefa"}, "tema": {"t": "Tema (theme)", "h": "<p>Plugin que controla a apresentação visual do site público. Pode oferecer configurações próprias e sua disponibilidade depende da instalação.</p><p><strong>Exemplo.</strong> A Gerente seleciona um tema aprovado e confere contraste e navegação no site da Revista.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> Aparência; <a href=\"#plugin\">plugin</a>; <a href=\"#site-da-revista\">site da Revista</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Manage Appearance and Navigation Menus”; PKP-JM, “Appearance”.</small></p>", "g": "tema"}, "template-de-e-mail": {"t": "Template de e-mail (email template)", "h": "<p>Modelo reutilizável de mensagem associado a ações do fluxo. Pode ser editado pela Revista, mas precisa ser revisto para não enviar instruções desatualizadas.</p><p><strong>Exemplo.</strong> A equipe adapta o convite de avaliação para incluir prazo e política de confidencialidade.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#notificacao\">Notificação</a>; <a href=\"#decisao-editorial\">decisão editorial</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> LOJS 3.4, “Workflow Settings — Emails”; PKP-EW, capítulos “Submission” e “Review”.</small></p>", "g": "template-de-e-mail"}, "triagem-editorial": {"t": "Triagem editorial (editorial screening)", "h": "<p>Conferência inicial de escopo, requisitos, integridade de arquivos e condições para seguir ao fluxo. Pode resultar em solicitação de ajuste, envio à avaliação ou decisão de triagem.</p><p><strong>Exemplo.</strong> A equipe verifica anonimização e documentos obrigatórios antes de convidar <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadores</button>.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#decisao-de-triagem\">Decisão de triagem</a>; <a href=\"#submissao\">Submissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “The Submission Stage”; Livro Crivo, “Estágio 1 — Submissão”.</small></p>", "g": "triagem-editorial"}, "url-canonica": {"t": "URL canônica (canonical URL)", "h": "<p>Endereço preferencial e estável de uma página pública, usado para reduzir ambiguidades entre URLs equivalentes. Deve apontar para a versão pública correta do objeto.</p><p><strong>Exemplo.</strong> O artigo usa a landing page oficial como URL de referência e destino do DOI.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> DOI; <a href=\"#landing-page\">landing page</a>; <a href=\"#indexacao\">indexação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Archive &amp; SEO”; LOJS 3.4, “Distribution Settings — Search Indexing”.</small></p>", "g": "url-canonica"}, "usuario": {"t": "Usuário (user)", "h": "<p>Pessoa com conta no OJS, à qual podem ser designados um ou mais papéis em uma ou mais Revistas. Conta, perfil, papel e contribuição autoral são conceitos diferentes.</p><p><strong>Exemplo.</strong> Uma mesma pessoa atua como <button type=\"button\" class=\"papel\" data-termo=\"papel-autor\" aria-haspopup=\"dialog\">Autora</button> em uma submissão e <button type=\"button\" class=\"papel\" data-termo=\"papel-avaliador\" aria-haspopup=\"dialog\">Avaliadora</button> em outra.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#conta\">Conta</a>; <a href=\"#papel\">papel</a>; <a href=\"#contribuinte\">contribuinte</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Manage Users and Roles”; Livro Crivo, “Conta, papel, permissão, designação e responsabilidade”.</small></p>", "g": "usuario"}, "ver-usuario-convidado": {"t": "Usuário convidado", "h": "<p class=\"remissao\">Ver <a href=\"#convite\"><strong>Convite</strong></a> e <a href=\"#usuario\"><strong>Usuário</strong></a>.</p>", "g": "ver-usuario-convidado"}, "versao": {"t": "Versão (version)", "h": "<p>Estado identificável de um arquivo ou publicação preservado para distinguir alterações ao longo do tempo. No pós-publicação, uma nova versão deve ser usada para mudanças substanciais, mantendo a anterior acessível conforme a política.</p><p><strong>Exemplo.</strong> A correção de resultados leva à publicação de uma nova versão, com data e indicação próprias.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#publicacao\">Publicação</a>; pós-publicação; correção.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Publication — Use Versioning for Substantial Changes to Published Content”.</small></p>", "g": "versao"}, "vocabulario-controlado": {"t": "Vocabulário controlado (controlled vocabulary)", "h": "<p>Lista estruturada de termos autorizados usada para tornar metadados mais consistentes e recuperáveis. O OJS 3.5 adiciona suporte a vocabulários externos em campos compatíveis.</p><p><strong>Exemplo.</strong> A Revista orienta a seleção de assuntos a partir de um vocabulário institucional.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#indexacao\">Indexação</a>; <a href=\"#metadados\">metadados</a>; palavras-chave.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-RN, “External Vocabulary Support”.</small></p>", "g": "vocabulario-controlado"}, "xml": {"t": "XML", "h": "<p>Formato estruturado usado em importação, exportação, interoperabilidade e algumas composições publicadas. Um XML bem-formado não é, por si só, garantia de validade no esquema ou aceitação por serviço externo.</p><p><strong>Exemplo.</strong> A equipe exporta metadados em XML e valida o arquivo antes de usá-lo em outra plataforma.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#importacao-e-exportacao\">Importação e exportação</a>; <a href=\"#oai-pmh\">OAI-PMH</a>; validação.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-RN, “Import/Export”; PKP-EW, “Production — Galley Formats”.</small></p>", "g": "xml"}, "papel-administrador-do-portal": {"t": "Administrador do Portal", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Administra a instalação do OJS, gerencia os Periódicos hospedados e acessa as configurações gerais do Portal. Pode gerenciar idiomas e plugins e executar tarefas de manutenção disponíveis no OJS.</p><h3>No glossário</h3><p>Papel de maior amplitude, responsável por configurações de toda a instalação, Revistas hospedadas, idiomas, plugins e manutenção. Seu acesso é global e não depende de designação a uma submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-administrador-do-portal\" aria-haspopup=\"dialog\">Administrador do Portal</button> habilita um idioma e cria a Revista Crivo; a equipe editorial configura a Revista depois.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#gerente-da-revista\">Gerente da Revista</a>; <a href=\"#portal\">Portal</a>; <a href=\"#revista-hospedada\">Revista hospedada</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-SA, “Access the Administration Menu”, “Configure OJS Site Settings” e “Create and Manage Hosted Journals”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "administrador-do-portal"}, "papel-gerente-da-revista": {"t": "Gerente da Revista", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Acessa o fluxo editorial completo e as configurações da Revista. Gerencia usuários, papéis e convites, acompanha as filas de submissões e pode criar e publicar números.</p><h3>No glossário</h3><p>Papel que configura a Revista, fluxo, usuários, papéis, site, distribuição e plugins autorizados. Seu acesso é amplo dentro da Revista, mas não equivale à administração de todo o Portal.</p><p><strong>Exemplo.</strong> A Gerente cria seções, ajusta diretrizes e convida integrantes da equipe.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#administrador-do-portal\">Administrador do Portal</a>; <a href=\"#editor\">Editor</a>; <a href=\"#revista\">Revista</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, conjunto do guia; PKP-SA, “Configure Journal-Specific Settings”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "gerente-da-revista"}, "papel-editor-da-revista": {"t": "Editor da Revista", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Atua no painel editorial, da triagem à publicação. Pode designar responsáveis, convidar Avaliadores, solicitar revisões, registrar decisões e conferir metadados. O acesso às configurações da Revista depende das permissões do papel.</p><h3>No glossário</h3><p>Papel editorial amplo que costuma acessar submissões, designar responsáveis, tomar decisões e conduzir a publicação. O alcance exato depende das permissões do papel e, em certas telas, da designação à submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button> designa uma <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button>, acompanha os pareceres e registra a decisão.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#editor-de-secao\">Editor de Seção</a>; <a href=\"#gerente-da-revista\">Gerente da Revista</a>; <a href=\"#designacao\">designação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "editor"}, "papel-editor-de-secao": {"t": "Editor de Seção", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Acompanha as submissões sob sua responsabilidade. Pode conduzir a avaliação, conversar com a autoria e recomendar ou registrar decisões, conforme as permissões do papel.</p><h3>No glossário</h3><p>Papel editorial que gerencia submissões de seções designadas ou registros aos quais foi designado. A configuração pode permitir acesso apenas às submissões designadas ou a toda a seção.</p><p><strong>Exemplo.</strong> Uma <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-secao\" aria-haspopup=\"dialog\">Editora de Seção</button> acompanha somente os artigos de “Estudos de Controle”.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#editor\">Editor</a>; <a href=\"#secao\">seção</a>; <a href=\"#designacao\">designação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles” e “Edit or Add a Role”; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "editor-de-secao"}, "papel-assistente-editorial": {"t": "Assistente Editorial", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Acessa as submissões e etapas em que presta apoio, conforme o papel configurado na Revista e a designação recebida. Pode, por exemplo, conferir documentos e acompanhar pendências.</p><h3>No glossário</h3><p>Papel configurável de apoio editorial, com acesso definido pelo conjunto de permissões e pelos estágios designados ao papel. Na Revista Crivo, o nome e o alcance efetivos precisam ser confirmados localmente.</p><p><strong>Exemplo.</strong> Uma Assistente recebe acesso à Editoração de uma submissão para conferir arquivos, sem administrar o Portal.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#designacao\">Designação</a>; <a href=\"#papel\">papel</a>; <a href=\"#permissao\">permissão</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles” e “Edit or Add a Role”; Locale 3.5, <code>user.role.journalAssistant</code>; Livro Crivo, “Papéis usados no curso”.</small></p>", "g": "assistente-da-revista"}, "papel-editor-de-texto": {"t": "Editor de Texto", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Trabalha nos arquivos e nas discussões da etapa de Edição de Texto das submissões designadas. Pode revisar o manuscrito, esclarecer dúvidas com a autoria e enviar o arquivo editado.</p><h3>No glossário</h3><p>Papel responsável pela revisão editorial e linguística dos arquivos aceitos e pela consolidação do texto antes da editoração. O acesso normalmente requer designação à submissão.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-de-texto\" aria-haspopup=\"dialog\">Editor de Texto</button> padroniza o manuscrito, consulta a autoria e envia o arquivo final à Editoração.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#edicao-de-texto\">Edição de texto</a>; <a href=\"#arquivo-final-editado\">arquivo final editado</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Copyediting — Assign a Copyeditor”; PKP-JM, “Users — Roles”.</small></p>", "g": "editor-de-texto"}, "papel-diagramador": {"t": "Diagramador", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Atua na etapa de Editoração das submissões designadas. Prepara e carrega as composições finais para publicação (galleys), como PDF ou HTML.</p><h3>No glossário</h3><p>Papel de editoração que prepara ou incorpora formatos finais de publicação. O acesso costuma depender da designação à submissão e dos estágios permitidos ao papel.</p><p><strong>Exemplo.</strong> O <button type=\"button\" class=\"papel\" data-termo=\"papel-diagramador\" aria-haspopup=\"dialog\">Editor de Layout</button> recebe o arquivo editado e gera PDF e HTML.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#composicao-final\">Composição final</a>; <a href=\"#editoracao\">Editoração</a>; <a href=\"#prova\">prova</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-EW, “Production — Assign a Layout Editor”; PKP-JM, “Users — Roles”.</small></p>", "g": "editor-de-layout"}, "papel-leitor-de-prova": {"t": "Leitor de Prova", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Acessa as provas encaminhadas para conferência e as discussões relacionadas à tarefa. Pode sinalizar problemas de apresentação, paginação ou links antes da publicação.</p>", "g": ""}, "papel-avaliador": {"t": "Avaliador", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Acessa a avaliação para a qual foi convidado. Pode aceitar ou recusar o convite e, ao aceitar, consultar as diretrizes, acessar os arquivos liberados para a rodada e enviar o parecer e a recomendação.</p><h3>No glossário</h3><p>Papel que permite responder a convites e realizar avaliações designadas. O acesso é limitado às avaliações designadas e às informações liberadas pela configuração e pelo <button type=\"button\" class=\"papel\" data-termo=\"papel-editor-da-revista\" aria-haspopup=\"dialog\">Editor</button>.</p><p><strong>Exemplo.</strong> Carla aceita o convite, consulta as diretrizes, envia seu parecer e conclui a avaliação.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#avaliacao-por-pares\">Avaliação por pares</a>; <a href=\"#convite\">convite</a>; <a href=\"#rodada-de-avaliacao\">rodada de avaliação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-RV, “Respond to a Review Request” e “Conduct a Review”; PKP-JM, “Users — Get to Know Permissions and Roles”.</small></p>", "g": "avaliador"}, "papel-autor": {"t": "Autor", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Acessa o próprio perfil e as submissões vinculadas à sua conta. Pode iniciar uma submissão, acompanhar seu andamento, consultar comunicações e enviar arquivos revisados. A edição de metadados e dados de autoria durante o fluxo depende da autorização editorial.</p><h3>No glossário</h3><p>Papel que permite criar submissões e acompanhar aquelas vinculadas à própria conta. O acesso editorial a outras submissões não decorre desse papel.</p><p><strong>Exemplo.</strong> Ana envia um artigo, responde à solicitação de revisão e acompanha a decisão pelo painel.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#contribuinte\">Contribuinte</a>; <a href=\"#submissao\">submissão</a>; <a href=\"#usuario\">usuário</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; Livro Crivo, “Cadastro, perfil e papel de Autor”.</small></p>", "g": "autor"}, "papel-leitor": {"t": "Leitor", "h": "<p class=\"painel-acesso\"><strong>O que costuma acessar e fazer:</strong> Consulta o site público da Revista, pesquisa no acervo e acessa os números, artigos e arquivos publicados conforme as condições de acesso. Pode receber avisos por e-mail quando o recurso estiver habilitado.</p><h3>No glossário</h3><p>Papel de usuário voltado ao acompanhamento e acesso ao conteúdo público; não concede participação editorial. Algumas notificações podem depender de cadastro e consentimento.</p><p><strong>Exemplo.</strong> Um <button type=\"button\" class=\"papel\" data-termo=\"papel-leitor\" aria-haspopup=\"dialog\">Leitor</button> cadastrado recebe aviso de novo número, se a Revista usar esse recurso.</p><p class=\"relacionados\"><strong>Termos relacionados:</strong> <a href=\"#usuario\">Usuário</a>; <a href=\"#notificacao\">notificação</a>.</p><p class=\"fonte\"><small><strong>Fonte:</strong> PKP-JM, “Users — Get to Know Permissions and Roles”; PKP-EW, “Publication — Notify Readers”.</small></p>", "g": "leitor"}};
